		/**
		 * Returns a new populated Department
		 * 
		 * @return Department
		 */
		protected Department generateNewEntity() {
			Department entity = new Department( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  null,  null,  new HashSet<>(),  new HashSet<>(),  null );
			
			return( entity );
		}

